targets.query:
import "array"

buckets_arr = ${bucket:json}

union(tables: buckets_arr |> array.map(fn: (x) =>
  from(bucket: x)
    |> range(start: -5m)
    |> filter(fn: (r) => r._measurement == "http_response" and r.via == "${via}" and r._field == "response_time")
    |> keep(columns: ["_time", "_value"])
))
  |> group()
  |> mean()
